// ----------------------------------------------------------------
// Word (.docx) export — fills a Word template with one meeting's data so
// officers can download an editable agenda and adjust it in Word.
//
// The template is the club's own upload — one for Chinese meetings
// (clubs.settings.word_template_url) and one for English meetings
// (word_template_url_en) — or the bundled default
// (public/templates/agenda-default.docx, generated by
// scripts/build-word-template.mjs). A club that uploaded a template for the
// meeting's language also gets its PDF / JPG in that layout (see
// wordLayoutUrl() and /api/word-render); without one, PDF / JPG follow the
// web agenda. Templates mark fields with {{標記}}; loops
// repeat a table row: {{#演講}} … {{/演講}} placed in the cells of one row.
//
// Role and meeting marks come from the role catalog (lib/meetingRoles.json),
// so a role added there is a Word mark too; a club's own roles are marked by
// their name. WORD_FIELDS / WORD_LOOPS list the rest. Pictures (WORD_PICTURES)
// are placeholder pictures whose alt text is the mark, e.g. {{主題圖片}}; the
// meeting's picture replaces them, cropped to the placeholder's box. The club modal's help,
// the upload check (unknown marks) and the README all come from these lists.
// ----------------------------------------------------------------
import { withBase } from './basePath';
import {
  MEETING_ROLES, MEETING_META, ROLE_GROUP_DEFS, builtinRoleValue, builtinWordMarks,
  clubCustomRoles, customRoleValue,
} from './meetingRoles';
import { pathwayPairs } from './pathways';
import { fitMarkedTables } from './wordFit';

export const WORD_DEFAULT_TEMPLATE = withBase('/templates/agenda-default.docx');
export const WORD_DELIMITERS = { start: '{{', end: '}}' };

