// The club modal's upload fields (appended to every template's manifest: a
// Word template belongs to the club, not to its agenda template).
export const WORD_TEMPLATE_FIELD = {
  key: 'word_template_url', label: '中文場 Word 範本（.docx）', type: 'word', store: 'setting',
  group: 'template', section: 'Word 匯出範本', lang: 'zh', help: true,
};
export const WORD_TEMPLATE_EN_FIELD = {
  key: 'word_template_url_en', label: '英文場 Word 範本（.docx）', type: 'word', store: 'setting',
  group: 'template', section: 'Word 匯出範本', lang: 'en',
};
export const WORD_TEMPLATE_FIELDS = [WORD_TEMPLATE_FIELD, WORD_TEMPLATE_EN_FIELD];

/**
 * The club's own template that sets the PDF / JPG layout of a meeting in
 * `lang` — or null, and PDF / JPG follow the web agenda. Strict per language:
 * an English meeting with only a Chinese template keeps the web layout,
 * since the Chinese template would print Chinese labels on it.
 */
export function wordLayoutUrl(club, lang) {
  const set = (club && club.settings) || {};
  return (lang === 'en' ? set.word_template_url_en : set.word_template_url) || null;
}

/**
 * The template 下載 Word fills: the language's own, then the Chinese one
 * (better than nothing for an editable file), then null = the bundled default.
 */
export function wordDownloadUrl(club, lang) {
  const set = (club && club.settings) || {};
  return wordLayoutUrl(club, lang) || set.word_template_url || null;
}

const OFFICER_KEYS = {
  會長: 'officer_president', 教育副會長: 'officer_vpe', 會員副會長: 'officer_vpm', 公關副會長: 'officer_vppr',
  秘書: 'officer_secretary', 財務長: 'officer_treasurer', 事務長: 'officer_saa',
};

/** Every mark a template may use for this club (its own roles included). */
export function wordKnownTags(club) {
  const tags = new Set(Object.values(WORD_FIELDS).flat().map(([k]) => k));
  Object.entries(WORD_LOOPS).forEach(([loop, { fields }]) => {
    tags.add(loop);
    fields.forEach(([k]) => tags.add(k));
  });
  clubCustomRoles(club).forEach((r) => tags.add(r.zh));
  return tags;
}

/**
 * The values a template is filled with. `data` is the meeting's full saved
 * data (roles the agenda editor doesn't show included). `ctx` carries the
 * agenda page's own helpers so names and times come out exactly as on the
 * printed agenda: { times (calcTimes()), displayMember, formatDate,
 * varietySession, pathwayLabel, durationLabels, signals }.
 */
export function buildWordData(data, club, ctx) {
  const { times, displayMember, formatDate, varietySession, pathwayLabel } = ctx;
  const DL = ctx.durationLabels || {};
  const set = (club && club.settings) || {};
  const who = (v) => displayMember(v) || '';
  const speeches = (data.speeches || []).filter((sp) => sp.title || sp.speaker);
  const evaluators = data.evaluators || [];
  const evalEvaluators = (data.evalEvaluators || []).filter(Boolean);
  const customs = clubCustomRoles(club);

  const out = {
    分會名稱: (club && (club.name_zh || club.name)) || '',
    分會英文名稱: (club && club.name_en) || '',
    分會編號: (club && club.charter_no) || '',
    分會網站: set.website || '',
    例會時間說明: set.scheduleZh || '',
    成立日: (club && club.founded_date) || '',
    入場費: (club && club.fee) || '',
    標語: set.slogan || '',
    交通: set.transit || '',
    結尾句: set.closingLine || '',
    近期例會: set.upcomingMeetings || '',
    特別活動: set.specialEvent || '',
    入會費用: set.membershipFee || '',
    例會日期: data.meetingDate ? formatDate(data.meetingDate) : '',
    時間: data.timeRange || '',
    地點: data.venueInfo || '',
    報到時間: times.receptionStart,
    開場時間: times.openingStart,
    多元單元時間: varietySession.enabled ? times.speechStart : '',
    演講時間: times.preparedSpeechStart,
    合照時間: times.photoStart,
    即席時間: times.topicsStart,
    講評時間: times.evalStart,
    閉幕時間: times.closingStart,
    分享時間: times.sharingStart,
    休息分鐘: String(times.intermissionMins),
    報到分鐘: String(times.receptionMins),
    開場分鐘: String(times.openingMins),
    多元單元分鐘: varietySession.enabled ? String(times.varietyMins) : '',
    演講分鐘: String(times.speechMins),
    合照分鐘: String(times.photoMins),
    即席分鐘: String(times.topicsMins),
    講評分鐘: String(times.evalMins),
    閉幕分鐘: String(times.closingMins),
    分享分鐘: String(times.sharingMins),
    計時員報告時長: DL.timerReport || '',
    贅語報告時長: DL.ahReport || '',
    語言講評時長: DL.langEval || '',
    總講評時長: DL.generalEval || '',
    演講: speeches.map((sp, i) => ({
      序號: String(i + 1), 講題: sp.title || '', 講者: who(sp.speaker),
      時長: sp.duration || "5'-7'", 專案: pathwayLabel ? pathwayLabel(sp) : '',
    })),
    講評員: evaluators.map((ev, i) => ({
      序號: String(i + 1), 姓名: who(ev), 講者: speeches[i] ? who(speeches[i].speaker) : '',
      時長: DL.evaluator || '', 國語: !!(speeches[i] && speeches[i].speechLang === 'zh'),
    })),
    講評員講評: evalEvaluators.map((ev, i) => ({ 序號: String(i + 1), 姓名: who(ev), 時長: DL.evalEvaluator || '' })),
    // A one-item list (row shown) or empty (row removed).
    多元單元: varietySession.enabled
      ? [{ 主持人: who(varietySession.host), 時間: times.speechStart, 分鐘: String(times.varietyMins) }] : [],
    學習路徑: pathwayPairs('zh').map(([code, name]) => ({ 代碼: code, 名稱: name })),
  };
  MEETING_META.forEach((m) => { out[m.word] = data[m.key] || ''; });
  MEETING_ROLES.forEach((r) => { out[r.word] = who(builtinRoleValue(data, r)); });
  customs.forEach((r) => { out[r.zh] = who(customRoleValue(data, r.id)); });
  Object.entries(OFFICER_KEYS).forEach(([tag, key]) => { out[tag] = set[key] || ''; });
  // As on the agenda: a bare number of minutes gets its ', 2'30" stays.
  const sig = (v) => (v == null || v === '' ? '' : /^\d+$/.test(String(v)) ? `${v}'` : String(v));
  const signals = ctx.signals || {};
  Object.entries(SIGNAL_MARKS).forEach(([cat, name]) => {
    const o = signals[cat] || {};
    out[`${name}綠牌`] = sig(o.g);
    out[`${name}黃牌`] = sig(o.y);
    out[`${name}紅牌`] = sig(o.r);
  });
  out.即席講者時間 = signals.ttSpeakerSpec || '';

  // 所有角色: everyone assigned, group by group as on the 角色 page.
  const all = [];
  const push = (role, v) => { if (v) all.push({ 角色: role, 姓名: who(v) }); };
  const groupRoles = (g) => MEETING_ROLES.filter((r) => r.group === g.key)
    .forEach((r) => push(r.zh, builtinRoleValue(data, r)));
  ROLE_GROUP_DEFS.forEach((g) => {
    if (g.key === 'speech') {
      speeches.forEach((sp, i) => push(`指定演講者 #${i + 1}`, sp.speaker));
    } else if (g.key === 'eval') {
      // As on the agenda: evaluators, 語言講評 / 總講評, then 講評員講評.
      evaluators.forEach((ev, i) => push(`個別講評員 #${i + 1}`, ev));
      groupRoles(g);
      evalEvaluators.forEach((ev, i) => push(`講評員講評 #${i + 1}`, ev));
    } else if (g.key === 'custom') {
      customs.forEach((r) => push(r.zh, customRoleValue(data, r.id)));
    } else {
      groupRoles(g);
    }
  });
  out.所有角色 = all;
  return out;
}

async function loadEngine() {
  const [{ default: PizZip }, { default: Docxtemplater }] = await Promise.all([import('pizzip'), import('docxtemplater')]);
  return { PizZip, Docxtemplater };
}

// docxtemplater error ids → what to fix, in the club officer's words.
const ERROR_ZH = {
  unclosed_loop: (t) => `迴圈 {{#${t}}} 沒有對應的 {{/${t}}}`,
  unopened_loop: (t) => `{{/${t}}} 前面沒有對應的 {{#${t}}}`,
  closing_tag_does_not_match_opening_tag: (t) => `迴圈的開頭與結尾標記不一致（${t}）`,
  unclosed_tag: (t) => `標記 {{${t} 缺少結尾的 }}`,
  unopened_tag: (t) => `標記 ${t}}} 缺少開頭的 {{`,
  duplicate_open_tag: (t) => `標記開頭重複了 {{（${t}）`,
  duplicate_close_tag: (t) => `標記結尾重複了 }}（${t}）`,
};

/** Readable list of a docxtemplater error's problems (bad / unclosed marks). */
export function wordTemplateErrors(e) {
  const list = (e && e.properties && e.properties.errors) || [e];
  return list.map((err) => {
    const p = err.properties || {};
    const tag = p.xtag || '';
    if (ERROR_ZH[p.id]) return ERROR_ZH[p.id](tag);
    return tag ? `${p.explanation || err.message}（${tag}）` : (p.explanation || err.message);
  });
}

/**
 * Check an uploaded template before it is saved. Returns
 * { errors: [..] (template unusable), unknown: [..] (marks we don't fill) }.
 */
export async function checkWordTemplate(arrayBuffer, club) {
  const { PizZip, Docxtemplater } = await loadEngine();
  // docxtemplater calls `parser` once per mark (loop names included) while it
  // compiles the template, which is all we need to list the marks used.
  const used = new Set();
  const parser = (tag) => { used.add(tag.trim()); return { get: (scope) => (scope ? scope[tag] : undefined) }; };
  try {
    new Docxtemplater(new PizZip(arrayBuffer), {
      paragraphLoop: true, linebreaks: true, delimiters: WORD_DELIMITERS, parser, errorLogging: false,
    });
  } catch (e) {
    return { errors: wordTemplateErrors(e), unknown: [] };
  }
  const known = wordKnownTags(club);
  return { errors: [], unknown: [...used].filter((k) => !known.has(k)) };
}

// The picture as JPEG bytes, cropped (centred) to `ratio` = width / height —
// the placeholder's box, like the agenda's object-fit: cover.
async function coverJpeg(src, ratio) {
  const img = new Image();
  await new Promise((resolve, reject) => { img.onload = resolve; img.onerror = reject; img.src = src; });
  const iw = img.naturalWidth;
  const ih = img.naturalHeight;
  const [sw, sh] = iw / ih > ratio ? [ih * ratio, ih] : [iw, iw / ratio];
  const canvas = document.createElement('canvas');
  canvas.width = Math.round(Math.min(sw, 1600));
  canvas.height = Math.round(canvas.width / ratio);
  canvas.getContext('2d').drawImage(img, (iw - sw) / 2, (ih - sh) / 2, sw, sh, 0, 0, canvas.width, canvas.height);
  const blob = await new Promise((resolve) => canvas.toBlob(resolve, 'image/jpeg', 0.92));
  return new Uint8Array(await blob.arrayBuffer());
}

// Swap each placeholder picture whose alt text is {{mark}} for pictures[mark]
// (a data URL). Marks without a picture keep their placeholder.
async function fillPictures(zip, pictures) {
  const docPath = 'word/document.xml';
  const relsPath = 'word/_rels/document.xml.rels';
  let xml = zip.file(docPath).asText();
  let rels = zip.file(relsPath).asText();
  const drawings = xml.match(/<w:drawing>[\s\S]*?<\/w:drawing>/g) || [];
  let n = 0;
  for (const d of drawings) {
    const mark = (d.match(/<wp:docPr\b[^>]*\bdescr="\{\{([^}"]+)\}\}"/) || [])[1];
    const src = mark && pictures[mark.trim()];
    const ext = d.match(/<wp:extent cx="(\d+)" cy="(\d+)"/);
    if (!src || !ext) continue;
    let bytes;
    try {
      bytes = await coverJpeg(src, Number(ext[1]) / Number(ext[2]));
    } catch (e) {
      console.warn(`Word：${mark} 圖片無法讀取，保留佔位圖`, e);
      continue;
    }
    n += 1;
    const id = `rIdWordPic${n}`;
    zip.file(`word/media/word_pic_${n}.jpeg`, bytes);
    rels = rels.replace('</Relationships>',
      `<Relationship Id="${id}" Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/image" Target="media/word_pic_${n}.jpeg"/></Relationships>`);
    xml = xml.replace(d, d.replace(/r:embed="[^"]*"/, `r:embed="${id}"`));
  }
  if (!n) return;
  zip.file(docPath, xml);
  zip.file(relsPath, rels);
  const typesPath = '[Content_Types].xml';
  const types = zip.file(typesPath).asText();
  if (!/Extension="jpeg"/i.test(types)) {
    zip.file(typesPath, types.replace('</Types>', '<Default Extension="jpeg" ContentType="image/jpeg"/></Types>'));
  }
}

/**
 * Fill `arrayBuffer` (a .docx) with `values` and `pictures` ({ mark: data URL },
 * see WORD_PICTURES); resolves to a .docx Blob.
 */
export async function fillWordTemplate(arrayBuffer, values, pictures = {}) {
  const { PizZip, Docxtemplater } = await loadEngine();
  const doc = new Docxtemplater(new PizZip(arrayBuffer), {
    paragraphLoop: true, linebreaks: true, delimiters: WORD_DELIMITERS,
    nullGetter: () => '', // a mark with no value prints nothing, not "undefined"
  });
  doc.render(values);
  await fillPictures(doc.getZip(), pictures);
  // Tables marked {{填滿:mm}} share that height over the rows this meeting
  // actually has (lib/wordFit.js) — after render, when the loops have run.
  const zip = doc.getZip();
  const docXml = zip.file('word/document.xml').asText();
  const fitted = fitMarkedTables(docXml);
  if (fitted !== docXml) zip.file('word/document.xml', fitted);
  return zip.generate({
    type: 'blob',
    mimeType: 'application/vnd.openxmlformats-officedocument.wordprocessingml.document',
  });
}
